            ld a, e		; Keys.cls 93
            rrca		; Keys.cls 94
            rrca		; Keys.cls 95
            rrca		; Keys.cls 96
            and 7		; Keys.cls 97
            inc a                   ; A = half row + 1 [98]
            ld b, a		; Keys.cls 99
            ld a, #7F		; Keys.cls 100
fn_keys_down_kdrow:		; Keys.cls 101
            rlca                    ; #FE for half row 0, #FD 1 ... #7F 7 [102]
            djnz fn_keys_down_kdrow		; Keys.cls 103
            ld b, a		; Keys.cls 104
            ld c, #FE		; Keys.cls 105
            in a, (c)		; Keys.cls 106
